import React, { useState, useEffect } from "react";
import axios from "axios";
import WelcomePage from "./WelcomePage";
import LoginRegister from "./LoginRegister"; // ✅ fixed path
import RoleSelection from "./RoleSelection"; // ✅ fixed path
//import Dashboard from "./Dashboard"; // Create a simple dashboard component

function App() {
  const [isLogin, setIsLogin] = useState(true);
  const [form, setForm] = useState({
    username: "",
    password: "",
    email: "",
    confirmPassword: "",
    pin: "",
    loginType: "password",
  });
  const [user, setUser] = useState(null);
  const [error, setError] = useState("");
  const [roleSelected, setRoleSelected] = useState(false); // Track if role is selected

  // Check token on load
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) {
      axios
        .get("http://localhost:5000/api/profile", {
          headers: { Authorization: `Bearer ${token}` },
        })
        .then((res) => setUser(res.data))
        .catch(() => localStorage.removeItem("token"));
    }
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError("");
  };

  const submitForm = async () => {
    if (!form.username || !form.password || (!isLogin && !form.email)) {
      setError("❌ All fields are required!");
      return;
    }
    if (!isLogin && form.password !== form.confirmPassword) {
      setError("❌ Passwords do not match!");
      return;
    }

    try {
      if (isLogin) {
        const res = await axios.post("http://localhost:5000/api/login", {
          username: form.username,
          password: form.password,
        });
        localStorage.setItem("token", res.data.token);
        setUser(res.data.user);
      } else {
        await axios.post("http://localhost:5000/api/register", form);
        alert("✅ Registration successful! Please login.");
        setIsLogin(true);
        setForm({
          username: "",
          password: "",
          email: "",
          confirmPassword: "",
          pin: "",
          loginType: "password",
        });
      }
    } catch (err) {
      setError(`❌ ${err.response?.data?.msg || "Server error"}`);
    }
  };

  const logout = () => {
    localStorage.removeItem("token");
    setUser(null);
    setRoleSelected(false);
  };

  // Called after role is selected in RoleSelection
  const handleRoleSelected = (role, subRole, customPurpose) => {
    setRoleSelected(true); // Mark role as selected
    setUser({ ...user, role, subRole, customPurpose });
  };

  // Render flow: Login/Register → RoleSelection → Dashboard
  if (user && !roleSelected) {
    return <RoleSelection user={user} onRoleSelected={handleRoleSelected} />;
  }

  if (user && roleSelected) {
    return <Dashboard user={user} logout={logout} />;
  }

  // Login/Register form
  return (
    <div className="flex h-screen items-center justify-center bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500">
      <div className="bg-white shadow-2xl p-8 rounded-3xl w-96">
        <h2 className="text-3xl font-bold text-center mb-6 text-purple-700">
          {isLogin ? "Login" : "Register"}
        </h2>

        {error && (
          <div className="bg-red-100 text-red-700 p-2 rounded mb-4 text-center font-medium">
            {error}
          </div>
        )}

        <form
          onSubmit={(e) => {
            e.preventDefault();
            submitForm();
          }}
        >
          {!isLogin && (
            <input
              name="email"
              value={form.email}
              onChange={handleChange}
              placeholder="Email"
              className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
            />
          )}

          <input
            name="username"
            value={form.username}
            onChange={handleChange}
            placeholder="Username"
            className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
          />

          <input
            type="password"
            name="password"
            value={form.password}
            onChange={handleChange}
            placeholder="Password"
            className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
          />

          {!isLogin && (
            <>
              <input
                type="password"
                name="confirmPassword"
                value={form.confirmPassword}
                onChange={handleChange}
                placeholder="Confirm Password"
                className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
              />
              <input
                name="pin"
                value={form.pin}
                onChange={handleChange}
                placeholder="Login PIN (optional)"
                className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
              />
              <select
                name="loginType"
                value={form.loginType}
                onChange={handleChange}
                className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
              >
                <option value="password">Password</option>
                <option value="pin">PIN</option>
                <option value="voice">Voice</option>
              </select>
            </>
          )}

          <button
            type="submit"
            className="w-full bg-purple-600 text-white p-3 rounded-lg hover:bg-purple-800 transition-colors duration-300 font-semibold"
          >
            {isLogin ? "Login" : "Register"}
          </button>
        </form>

        <p className="mt-4 text-center text-sm text-gray-600">
          {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
          <span
            onClick={() => {
              setIsLogin(!isLogin);
              setError("");
            }}
            className="text-indigo-600 cursor-pointer font-semibold hover:underline"
          >
            {isLogin ? "Register" : "Login"}
          </span>
        </p>
      </div>
    </div>
  );
}

export default App;
